class Solution {
public:
    int numberOfPaths(std::vector<std::vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        const int MOD = 1e9 + 7;
        std::vector<std::vector<std::vector<int>>> dp(m, std::vector<std::vector<int>>(n, std::vector<int>(k, 0)));

        dp[0][0][grid[0][0] % k] = 1;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int val = grid[r][c];
                for (int rem = 0; rem < k; rem++) {
                    int prev = (rem - val % k + k) % k;
                    if (r > 0) {
                        dp[r][c][rem] = (dp[r][c][rem] + dp[r - 1][c][prev]) % MOD;
                    }
                    if (c > 0) {
                        dp[r][c][rem] = (dp[r][c][rem] + dp[r][c - 1][prev]) % MOD;
                    }
                }
            }
        }
        return dp[m - 1][n - 1][0];
    }
};

